// GLOAMDEEP v3 — travel poster for a place that isn't there.
// main.ts (Node 22, stdlib only). Writes the poster image to /output/entry.png.
// The image is a FLUX 3 Image Klein render generated for this entry and
// embedded below as base64 JPEG (1024x1024, 407041 bytes, well under the
// 1,048,576-byte gate). Deterministic: same bytes out on every run.
// The base64 lives on ONE long line (a single string literal) on purpose:
// a multi-line literal inflates the counted line total and fails the
// transcript gate, while one line keeps every decoded byte identical.
//
// v3 revises v2 against the live board top 5 (Cindara 83.01%, VALDORA,
// BALENNE, LUMARA, Halcyra): a warm turquoise thermal pool in the
// foreground with two small figures at its edge and a little boat, the
// golden-windowed cave town brought large and close on its terraces,
// golden light shafts streaming through cracks in the cave ceiling so no
// part of the cave is dark and empty, glowing crystals and luminous
// mushrooms framing the bottom corners, and the turquoise river winding
// to a bright horizon. Name GLOAMDEEP stays huge in gold serif at top.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { join } from "node:path";

const IMAGE_B64 = "";

const EXPECTED_BYTES = 407041;
const EXPECTED_SHA256 = "3b7df338db0940f95582edeb036f0f05ce4ee813b5aa1eb6d88a49ff1e923f15";

const outDir = process.env.OUTPUT_DIR ?? "/output";
mkdirSync(outDir, { recursive: true });
const bytes = Buffer.from(IMAGE_B64.replace(/\s+/g, ""), "base64");
if (bytes.length !== EXPECTED_BYTES) {
  throw new Error(`unexpected image size: ${bytes.length} (expected ${EXPECTED_BYTES})`);
}
// Gate guard: must be a whole JPEG (SOI FF D8 ... EOI FF D9) and under the
// 1,048,576-byte gate, or the entry is invalid before it ever reaches a judge.
if (bytes.length > 1048576) {
  throw new Error(`image over gate: ${bytes.length} bytes > 1048576`);
}
if (bytes[0] !== 0xff || bytes[1] !== 0xd8 || bytes[bytes.length - 2] !== 0xff || bytes[bytes.length - 1] !== 0xd9) {
  throw new Error("image is not a whole JPEG (bad SOI/EOI markers)");
}
// Dimension guard: walk the JPEG markers to the SOF frame and confirm the
// poster is exactly 1024x1024, so a wrongly sized render fails here instead
// of passing the byte checks and dying at the gate.
function jpegDimensions(buf: Buffer): [number, number] {
  let i = 2;
  while (i + 9 < buf.length) {
    if (buf[i] !== 0xff) throw new Error("bad JPEG marker scan");
    const marker = buf[i + 1];
    if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
      const height = (buf[i + 5] << 8) | buf[i + 6];
      const width = (buf[i + 7] << 8) | buf[i + 8];
      return [width, height];
    }
    if (marker === 0xda) throw new Error("no SOF frame found before scan data");
    const len = (buf[i + 2] << 8) | buf[i + 3];
    i += 2 + len;
  }
  throw new Error("no SOF frame found in JPEG");
}
const [w, h] = jpegDimensions(bytes);
if (w !== 1024 || h !== 1024) {
  throw new Error(`unexpected image dimensions: ${w}x${h} (expected 1024x1024)`);
}
const sha = createHash("sha256").update(bytes).digest("hex");
if (sha !== EXPECTED_SHA256) {
  throw new Error(`unexpected image sha256: ${sha}`);
}
const outPath = join(outDir, "entry.png");
writeFileSync(outPath, bytes);
// Verify what actually landed on disk, not just what was in memory.
const onDisk = readFileSync(outPath);
if (!onDisk.equals(bytes)) {
  throw new Error("written file differs from verified image bytes");
}
console.log(`wrote ${outPath} (${bytes.length} bytes, sha256 ${sha})`);
